INSERT INTO `contact_messages` VALUES (1,'Sean Fordyce','sean@talentnavigation.com','Hi Michael,\r\n\r\nThis is a contract to hire position but they do want this person to come on full time after 6 months and we’re targeting someone around 105K plus benefits ($55/hr plus benefits while on contract). They would make this a direct hire right out of the gate but they avoid staffing fees by making it a CTH.\r\n\r\nWho you are:\r\nYou are a results-oriented self-starter who enjoys development and working with leading edge technologies to deliver enterprise and mobile solutions. You are passionate about what you do, can function at both a team and individual level, able to multitask, able to learn, teach and collaborate well in dynamic, and hands-on environments. \r\n\r\nWhat you will do:\r\nYou will join our agile development team as a Senior Web Developer who has extensive experience with software development. You will be involved in a wide range of software design, architecture and engineering projects in support of the organizations growth and will have the opportunity to immediately contribute and build your skills in a fast-paced environment. \r\n\r\nYou are experienced with:\r\n•	6+ years of experience with object-oriented PHP and a solid understanding of object-oriented concepts\r\n•	Experience working in a variety of languages (JavaScript, Python, etc.)\r\n•	Experience working in a GNU/Linux development environment\r\n•	Expert knowledge of frameworks such as Laravel, Cake, Symphony, etc. (Laravel preferred)\r\n•	Comfortable working in Agile methodologies\r\n•	Experience building and maintaining MySQL and SQL\r\n•	Experience using jQuery and other popular JS libraries, CSS libraries and responsive design\r\n•	Has experience working with third-party APIs\r\n•	Experience building services and working with APIs (REST, JSON, XML)\r\n•	Expert knowledge using version control and Git / GitHub\r\n•	Expert HTML/CSS and JavaScript skills\r\n•	IDE-PhpStorm experience (or equivalent)\r\n•	Solid and proven experience with WordPress development\r\n\r\nCode Expectations:\r\n•	Executes desired business logic\r\n•	Is tested\r\n•	Is clean and thoughtfully written with comments\r\n•	Is efficient\r\n•	Is delivered on time\r\n•	Doesn\'t take shortcuts\r\n•	Conforms to best practices\r\n\r\nKey responsibilities:\r\n•	Analyze, design, develop, and maintain PHP enterprise software using Laravel framework\r\n•	Write specifications, write code, complete programming, test and debug applications\r\n•	Build robust and functionally sophisticated capabilities\r\n•	Develop and commit organized and well-structured code\r\n•	Conduct rigorous testing, and identify and debug issues\r\n•	Tune solutions to optimize performance\r\n•	Remove inefficiencies and build for scale\r\n•	Identify ways to enhance the user experience\r\n•	Ensure proper documentation\r\n\r\nCheers,\r\nSean','2018-03-14 17:27:28','2018-03-14 17:27:28');
/*!40000 ALTER TABLE `contact_messages` ENABLE KEYS */;
UNLOCK TABLES;

