INSERT INTO `daily_reminders` VALUES (1,'Deb Martin (Councilor)','HALT: Refrain from talking to people when you\'re (H)ungry, (A)ngry, (L)onely, or (T)ired.','2018-03-21 05:17:01','2018-03-21 05:17:01'),(2,'How to Make Friends and Influence People','Don\'t criticize, condemn, or complain','2018-03-24 22:54:13','2018-03-24 22:55:08'),(3,'How to Make Friends and Influence People','Give honest, sincere appreciation','2018-03-24 22:54:37','2018-03-24 22:54:37'),(4,'How to Make Friends and Influence People','Arouse in the other person an eager want','2018-03-24 22:55:03','2018-03-24 22:55:03'),(5,'How to Make Friends and Influence People','Become genuinely interested in other people','2018-03-24 22:55:26','2018-03-24 22:55:26'),(6,'How to Make Friends and Influence People','Smile','2018-03-24 22:55:35','2018-03-24 22:55:35'),(7,'How to Make Friends and Influence People','Remember that a person\'s name is, to that person, the sweetest and most important sound in any language','2018-03-24 22:56:23','2018-03-24 22:56:23'),(8,'How to Make Friends and Influence People','Be a good listener; encourage people to talk about themselves','2018-03-24 22:56:58','2018-03-24 22:56:58'),(9,'How to Make Friends and Influence People','Talk in terms of the other person\'s interests','2018-03-24 22:57:13','2018-03-24 22:57:27'),(10,'How to Make Friends and Influence People','Make the other person feel important, and do so sincerely','2018-03-24 22:57:49','2018-03-24 22:57:49'),(11,'How to Make Friends and Influence People','The only way to get the best of an argument is to avoid it','2018-03-24 22:58:05','2018-03-24 22:58:05'),(12,'How to Make Friends and Influence People','If you\'re wrong, admit it quickly and emphatically','2018-03-24 22:58:42','2018-03-24 22:59:08'),(13,'How to Make Friends and Influence People','Begin in a friendly way','2018-03-24 22:59:22','2018-03-24 22:59:22'),(14,'How to Make Friends and Influence People','Get the other person saying \"yes, yes\" immediately (it\'s a psychological approach to continuing in that direction)','2018-03-24 23:00:17','2018-03-24 23:00:17'),(15,'How to Make Friends and Influence People','Let the other person do a majority of the talking','2018-03-24 23:00:31','2018-03-24 23:00:31'),(16,'How to Make Friends and Influence People','Let the other person think the idea was his/hers','2018-03-24 23:00:55','2018-03-24 23:00:55'),(17,'How to Make Friends and Influence People','Try honestly to see things from the other person\'s point of view','2018-03-24 23:01:24','2018-03-24 23:01:24'),(18,'How to Make Friends and Influence People','Be sympathetic with the other person\'s ideas and desires','2018-03-24 23:01:44','2018-03-24 23:01:44'),(19,'How to Make Friends and Influence People','Call attention to people\'s mistakes indirectly','2018-03-24 23:01:59','2018-03-24 23:01:59'),(20,'How to Make Friends and Influence People','Talk about your own mistakes first','2018-03-24 23:02:10','2018-03-24 23:02:10'),(21,'How to Make Friends and Influence People','Ask questions instead of giving direct orders','2018-03-24 23:02:22','2018-03-24 23:02:22'),(22,'How to Make Friends and Influence People','Let the other person save face','2018-03-24 23:02:32','2018-03-24 23:02:32'),(23,'How to Make Friends and Influence People','Praise the slightest improvement, praise every improvement','2018-03-24 23:02:50','2018-03-24 23:02:50'),(24,'How to Make Friends and Influence People','Give the other person a fine reputation to live up to','2018-03-24 23:03:05','2018-03-24 23:03:05'),(25,'How to Make Friends and Influence People','Use encouragement; make the fault seem easy to correct','2018-03-24 23:03:24','2018-03-24 23:03:24'),(26,'How to Make Friends and Influence People','Make the other person happy about doing the thing you suggest','2018-03-24 23:03:37','2018-03-24 23:03:37'),(49,'Extreme Ownership','Prioritize and execute','2018-03-24 23:18:02','2018-03-24 23:21:37'),(50,'Extreme Ownership','Relax, look around, make a call','2018-03-24 23:18:16','2018-03-24 23:18:16'),(51,'Extreme Ownership','A leader must remain calm and make the best decisions possible','2018-03-24 23:18:38','2018-03-24 23:18:38'),(52,'Extreme Ownership','Even the most competent leaders can get overwhelmed when trying to tackle too many issues at the same time','2018-03-24 23:19:10','2018-03-24 23:19:10'),(53,'Extreme Ownership','Layout contingency plans, try to guess what you\'ll encounter, and plan for those scenarios','2018-03-24 23:19:33','2018-03-24 23:19:33'),(54,'Extreme Ownership','Avoid target fixation, highest priorities can shift','2018-03-24 23:19:50','2018-03-24 23:19:50'),(55,'Extreme Ownership','Leaders are incapable of leading more than 6 to 10 people','2018-03-24 23:22:30','2018-03-24 23:22:30'),(56,'Extreme Ownership','Jr leaders should lead by telling their leaders what they\'re going to do rather than asking to do it','2018-03-24 23:22:55','2018-03-24 23:22:55'),(57,'Extreme Ownership','Hand responsibility down to front line leaders to decentralize leadership','2018-03-24 23:23:14','2018-03-24 23:23:14'),(58,'Extreme Ownership','Disseminate clear, concise direction to subordinate leaders answering clearly what and why','2018-03-24 23:23:39','2018-03-24 23:23:39'),(59,'Extreme Ownership','Prioritize and highlight top few things to keep in mind during the execution of a plan','2018-03-24 23:24:03','2018-03-24 23:24:03'),(60,'Extreme Ownership','Give simple instructions for easy tasks and compartmentalize them','2018-03-24 23:25:02','2018-03-24 23:25:02'),(61,'Extreme Ownership','Accept responsibility for failures','2018-03-24 23:25:20','2018-03-24 23:25:20'),(62,'Extreme Ownership','Establish higher standards','2018-03-24 23:25:29','2018-03-24 23:25:29'),(63,'Extreme Ownership','Accept that you can do what needs to be done to win','2018-03-24 23:25:41','2018-03-24 23:25:41'),(64,'Extreme Ownership','Rid yourself of discouraging thoughts','2018-03-24 23:25:54','2018-03-24 23:25:54'),(65,'Extreme Ownership','What does winning look like from leadership\'s perspective?','2018-03-24 23:26:10','2018-03-24 23:26:10'),(66,'Extreme Ownership','Put yourself in your leadership\'s shoes and ask yourself why they came to a decision','2018-03-24 23:26:38','2018-03-24 23:26:38'),(67,'Extreme Ownership','CHECK YOUR EGO!','2018-03-24 23:26:48','2018-03-24 23:26:48'),(68,'Extreme Ownership','Assume I\'m wrong, figure out how to make communication adjustments, and implement them','2018-03-24 23:27:05','2018-03-24 23:27:41'),(69,'Extreme Ownership','Consider ways to utilize other teams','2018-03-24 23:27:56','2018-03-24 23:27:56'),(70,'Extreme Ownership','Survey the strengths and contributions of other teams and consider how they may be useful','2018-03-24 23:28:18','2018-03-24 23:28:18'),(71,'Extreme Ownership','For bottlenecks with external sources, reach out and determine their obstacles and how you can help them help you better contribute to the overall mission','2018-03-24 23:28:56','2018-03-24 23:28:56'),(72,'Extreme Ownership','Keep it simple','2018-03-24 23:29:13','2018-03-24 23:29:13'),(73,'Extreme Ownership','Explain so even the lowest common denominator can understand','2018-03-24 23:29:32','2018-03-24 23:29:32'),(74,'Extreme Ownership','If you get lost in the explanation, it\'s too difficult','2018-03-24 23:29:49','2018-03-24 23:29:49'),(75,'Extreme Ownership','If your team gets lost in the explanation, it\'s too difficult','2018-03-24 23:30:05','2018-03-24 23:30:05'),(76,'Extreme Ownership','Complex plans add to confusion','2018-03-24 23:30:18','2018-03-24 23:30:18'),(77,'Extreme Ownership','Communication should be direct','2018-03-24 23:30:27','2018-03-24 23:30:27'),(78,'Who Moved My Cheese?','Learn to laugh at your own folly.  You can then let go and move on more quickly.','2018-04-04 13:58:27','2018-04-04 13:58:27'),(79,'Who Moved My Cheese?','Don\'t be afraid to change.  You\'re only holding onto the illusion of the \"old cheese\" which is no longer there.','2018-04-04 14:02:43','2018-04-04 14:02:43'),(80,'Who Moved My Cheese?','Keep life simple.  Don\'t overanalyze or complicate things.  When the situation changes, and the cheese moves, change yourself and move with \"the cheese.\"','2018-04-04 14:06:57','2018-04-04 14:06:57'),(81,'Who Moved My Cheese?','Reflect on the mistakes you make and use them to plan for the future:\r\n\r\n1. Be more aware of the need to keep things simple.\r\n\r\n2. Be flexible and move quickly.\r\n\r\n3. Do not overcomplicate matters or confused yourself.','2018-04-04 14:12:08','2018-04-04 14:12:08'),(82,'Who Moved My Cheese?','Recognize that there is always \"new cheese\" out there,. Go past your far and enjoy the adventure.','2018-04-04 14:14:15','2018-04-04 14:14:15'),(83,'Who Moved My Cheese?','Anticipate change.  Get ready for \"the cheese\" to move.','2018-04-04 14:16:45','2018-04-04 14:16:45'),(84,'Who Moved My Cheese?','Monitor change.  Smell \"the cheese\" often so you know when it\'s getting old.','2018-04-04 14:19:21','2018-04-04 14:19:21'),(85,'Who Moved My Cheese?','Adapt to change quickly.  The sooner you let go of \"old cheese,\" the sooner you can enjoy \"new cheese.\"','2018-04-04 14:21:38','2018-04-04 14:21:38'),(86,'Who Moved My Cheese?','Change.  Move with \"the cheese.\"','2018-04-04 14:22:18','2018-04-04 14:22:18'),(87,'Who Moved My Cheese?','Enjoy change.  Savor the adventure and enjoy the taste of \"new cheese.\"','2018-04-04 14:25:49','2018-04-04 14:25:49'),(88,'Who Moved My Cheese?','Be ready to change quickly and enjoy the change again.','2018-04-04 14:26:32','2018-04-04 14:26:32'),(89,'7 Habits of Highly Effective People','Independence: Be Proactive','2018-04-04 14:52:15','2018-04-04 14:52:15'),(90,'7 Habits of Highly Effective People','Independence: Begin with the end in mind.','2018-04-04 14:52:52','2018-04-04 14:52:52'),(91,'7 Habits of Highly Effective People','Independence: Put first things first','2018-04-04 14:53:10','2018-04-04 14:53:10'),(92,'7 Habits of Highly Effective People','Interdependence: Think win-win','2018-04-04 14:53:35','2018-04-04 14:53:35'),(93,'7 Habits of Highly Effective People','Interdependence: Seek first to understand, then to be understood','2018-04-04 14:53:57','2018-04-04 14:53:57'),(94,'7 Habits of Highly Effective People','Interdependence: Synergize','2018-04-04 14:54:24','2018-04-04 14:54:24'),(95,'7 Habits of Highly Effective People','Continual Improvement: Sharpen the saw','2018-04-04 14:54:52','2018-04-04 14:54:52'),(96,'The 8th Habit','Find your voice and inspire others to find theirs.','2018-04-04 14:55:30','2018-04-04 14:55:30'),(97,'The 4-hour Work Week','Ensure you constantly all yourself what you\'ve done today to make your life easier or better.','2018-04-18 13:32:08','2018-04-18 13:32:08'),(98,'7 Habits of Highly Effective People','Remember to evaluate P/PC (Production/Production Capability) Balance in scenarios that are not going well.','2018-05-23 14:34:09','2018-06-04 15:06:52'),(99,'7 Habits of Highly Effective People','Be Proactive: Use resourcefulness and initiative to conquer all things.','2018-05-29 14:44:14','2018-05-29 14:44:14'),(100,'7 Habits of Highly Effective People','Be Proactive: Remember to work within your circle of influence, and not within your circle of concern.','2018-06-04 15:07:22','2018-06-04 15:07:22'),(101,'7 Habits of Highly Effective People','Be Proactive: Remember that \"Love\" is a verb, and that you can always bring back the feeling of love using the verb.','2018-06-04 15:16:17','2018-06-04 15:16:17'),(102,'7 Habits of Highly Effective People','Remember to focus on the deterministic things that happen to you in a light of influence, meaning focus on what you can do to fix things rather than getting frustrated with the issues themselves.','2018-06-04 15:21:27','2018-06-04 15:21:27'),(103,'Jessica Miller','<p>Don\'t sell yourself short. Remember that if people are paying for your services, they want your services. Don\'t push them to take from others.</p>','2018-06-18 05:46:30','2024-05-09 12:51:09'),(104,'Jessica Miller','<p>Follow up with previous clients. Check in with them and make sure they\'re happy with the results. This will open up the door for them to ask for more.</p>','2018-06-18 05:47:18','2020-08-08 20:31:17'),(105,'Michael Miller','Inventory all of your tasks, figure out what you can automate, prioritize, and execute on it.','2018-08-15 15:58:03','2018-08-15 15:58:03'),(106,'7 Productivity Rules Elon Musk Says Every EffectiveLeader Should Embrace','<p>Stop holding large meetings.</p>','2020-08-08 20:18:38','2020-08-08 20:26:12'),(107,'7 Productivity Rules Elon Musk Says Every Effective Leader Should Embrace','<p>Stop holding frequent meetings.</p>','2020-08-08 20:20:17','2020-08-08 20:25:42'),(108,'7 Productivity Rules Elon Musk Says Every Effective Leader Should Embrace','<p>Feel free to walk out of meetings.</p>','2020-08-08 20:25:12','2020-08-08 20:25:12'),(109,'7 Productivity Rules Elon Musk Says Every Effective Leader Should Embrace','<p>Stop using acronyms and buzzwords.</p>','2020-08-08 20:27:13','2020-08-08 20:27:13'),(110,'7 Productivity Rules Elon Musk Says Every Effective Leader Should Embrace','<p>Stop using the (communication) chain of command.</p>','2020-08-08 20:28:33','2020-08-08 20:28:33'),(111,'7 Productivity Rules Elon Musk Says Every Effective Leader Should Embrace','<p>Stop limiting the communication between departments.</p>','2020-08-08 20:29:21','2020-08-08 20:29:21'),(112,'7 Productivity Rules Elon Musk Says Every Effective Leader Should Embrace','<p>Stop following stupid rules (Ask yourself if the role belongs in a Dilbert cartoon).</p>','2020-08-08 20:33:33','2020-08-08 20:33:33'),(113,'5 Disfunctions of a Team','<p>Absence of Trust</p>','2020-10-16 13:59:23','2020-10-21 13:52:10'),(114,'5 Disfunctions of a Team','<p>Inattention to results</p>','2020-10-21 13:53:11','2020-10-21 13:53:11'),(115,'5 Disfunctions of a Team','<p>Fear of conflict</p>','2020-10-23 13:55:32','2020-10-23 13:55:32'),(116,'5 Disfunctions of a Team','<p>Lack of commitment and failure to buy into decisions</p>','2020-10-23 14:02:15','2020-10-23 14:02:15'),(117,'5 Disfunctions of a Team','<p>Avoidance of accountability</p>','2020-10-23 14:05:57','2020-10-23 14:05:57'),(118,'How to sound and be more confident (https://digg.com/human-nature/link/how-to-sound-more-confident-vocabulary-0uRWD6TaHh?utm_source=digg)','<p>Replace \"I have to\" with \"I get to,\" and reframe your approach to things with a \"can try to\" attitude and not a \"can\'t do\" one.</p>','2022-09-19 18:17:25','2022-09-19 18:17:25'),(119,'How to sound and be more confident (https://digg.com/human-nature/link/how-to-sound-more-confident-vocabulary-0uRWD6TaHh?utm_source=digg)','<p>Omit \"should\" in a phrase, it puts on unnecessary pressure.</p>','2022-09-19 18:17:58','2022-09-19 18:17:58'),(120,'How to sound and be more confident (https://digg.com/human-nature/link/how-to-sound-more-confident-vocabulary-0uRWD6TaHh?utm_source=digg)','<p>Turn difficult moments (\"why me,\" \"shouldn\'t have,\" \"I failed\") into \"What am I learning from this\" moments.</p>','2022-09-19 18:18:19','2022-09-19 18:18:19'),(121,'How to sound and be more confident (https://digg.com/human-nature/link/how-to-sound-more-confident-vocabulary-0uRWD6TaHh?utm_source=digg)','<p>If things are \"complicated,\" feel free to say you \"don\'t understand this right now,\" and come back to it later.</p>','2022-09-19 18:18:39','2022-09-19 18:18:39'),(122,'How to sound and be more confident (https://digg.com/human-nature/link/how-to-sound-more-confident-vocabulary-0uRWD6TaHh?utm_source=digg)','<p>When life serves you \"unfair\" moments, keep positive with a \"I can deal with it\" frame of mind.</p>','2022-09-19 18:18:59','2022-09-19 18:18:59'),(123,'Successful (Dark Horse) Mindset - https://www.youtube.com/watch?v=AjnNYPtNa6A','<p>Know your micro-motives</p><p><br></p><ul><li>Learning</li><li>Inspiring</li><li>Organization through software</li></ul>','2022-10-19 21:32:40','2024-07-31 18:50:26'),(124,'Successful (Dark Horse) Mindset - https://www.youtube.com/watch?v=AjnNYPtNa6A','<p>Know your choices</p>','2022-10-19 21:33:13','2024-07-31 18:51:00'),(125,'Successful (Dark Horse) Mindset - https://www.youtube.com/watch?v=AjnNYPtNa6A','<p>Know your strategies</p>','2022-10-19 21:34:28','2024-07-31 18:51:11'),(126,'Successful (Dark Horse) Mindset - https://www.youtube.com/watch?v=AjnNYPtNa6A','<p>Ignore the destination</p>','2022-10-19 21:34:58','2024-07-31 18:51:20');
