INSERT INTO `drinks` VALUES (1,'Costa Sur Especial','<p>2 pts Orange Juice</p><p>2 pts Pineapple Juice</p><p>1 pt Grenedine</p><p>1 pt Coconut Syrup</p><p>2 pts Vodka</p><p>2 pts Coconut Rum</p>','2019-08-19 12:21:18','2019-09-11 18:50:31'),(2,'Manhattan','<ul><li>2 oz Whiskey</li><li>3/4 oz Vermouth</li><li>Cherry</li><li>Dash of bitters</li></ul><p><br></p><ol><li>Stir over ice</li><li>Strain into chilled glass</li></ol>','2019-09-14 08:56:10','2019-09-14 08:56:10'),(3,'Wikiwiki Colada','<ul><li>2 oz Coconut Vodka</li><li>4 oz pineapple juice</li></ul><p><br></p><p>Pour over ice</p>','2019-09-14 08:58:49','2019-09-14 08:58:49'),(4,'Loco Coco','<ul><li>2 oz Coconut Vodka</li><li>2 oz pineapple juice</li><li>2 oz guava juice</li></ul><p><br></p><p>pour over ice</p>','2019-09-14 09:00:23','2019-09-14 09:00:23'),(5,'Coco Ginger Fizz','<ul><li>2 oz Coconut vodka</li><li>3 pineapple wedges</li><li>3 oz ginger ale</li></ul><p><br></p><p>pour over ice</p><p><br></p>','2019-09-14 09:01:20','2019-09-14 09:01:20'),(6,'Mounds Bar','<ul><li>1 oz Coconut vodka</li><li>2 oz chocolate liqueur</li></ul><p><br></p><ol><li>Shake with ice</li><li>Strain into glass</li></ol>','2019-09-14 09:02:20','2019-09-14 09:02:20'),(7,'Coco Cola','<ul><li>2 oz Coconut vodka</li><li>4 oz coke</li></ul><p><br></p><ol><li>Squeeze lime</li><li>pour over ice</li></ol>','2019-09-14 09:06:33','2019-09-14 09:06:33'),(8,'Coco Cosmo','<ul><li>2 oz Coconut vodka</li><li>3/4 oz triple sec</li><li>3/4 oz cranberry juice</li><li>3/4 oz lime juice</li></ul><p><br></p><ol><li>Shake with ice</li><li>Strain into glass</li></ol>','2019-09-14 09:07:33','2019-09-14 09:07:33'),(9,'Coconut Passion','<ul><li>2 oz Coconut vodka</li><li>3 oz soda water</li><li>dash Angostura bitters</li></ul><p><br></p><ol><li>Squeeze of lime</li><li>pour over ice and stir</li></ol>','2019-09-14 09:08:26','2019-09-14 09:08:26'),(10,'Coconut Lagoon','<ul><li>2 oz Coconut vodka</li><li>1 oz blue curacao</li><li>2 oz pineapple juice</li></ul><p><br></p><ol><li>Shake with ice</li><li>Strain into glass</li></ol>','2019-09-14 09:09:08','2019-09-14 09:09:08'),(11,'Hawaiian Sunset','<ul><li>2 oz Coconut vodka</li><li>3 oz orange juice</li><li>1 oz cranberry juice</li></ul><p><br></p><p>pour over ice</p>','2019-09-14 09:09:45','2019-09-14 09:09:45'),(12,'Pineapple Cooler','<ul><li>2 oz Coconut vodka</li><li>2 oz pineapple juice</li><li>2 oz club soda</li></ul><p><br></p><p>pour over ice</p>','2019-09-14 09:10:18','2019-09-14 09:10:18'),(13,'Blue Lagoon','<ul><li>1 1/2 oz Coconut vodka</li><li>1 oz blue curacao</li><li>4 oz lemonade</li></ul><p><br></p><p>pour over ice</p>','2019-09-14 09:10:57','2019-09-14 09:10:57'),(14,'Hanauma Bay Breeze','<ul><li>2 oz Coconut vodka</li><li>2 oz pineapple juice</li><li>2 oz cranberry juice</li></ul><p><br></p><p>pour over ice</p>','2019-09-14 09:12:11','2019-09-14 09:12:11'),(15,'Hawaiiian Martini','<ul><li>3 oz Coconut vodka</li><li>1/2 oz dry vermouth</li></ul><p><br></p><ol><li>Shake with ice</li><li>Strain into glass</li></ol>','2019-09-14 09:13:38','2019-09-14 09:13:38'),(16,'Hawaiian Madras','<ul><li>2 oz Hawaiian vodka</li><li>3 oz orange juice</li><li>1 oz cranberry juice</li></ul><p><br></p><p>pour over ice</p>','2019-09-14 09:14:15','2019-09-14 09:14:15'),(17,'Waikiki Sunset','<ul><li>2 oz Coconut vodka</li><li>2 oz orange juice</li><li>2 oz pineapple juice</li></ul><p><br></p><p>pour over ice</p>','2019-09-14 09:14:40','2019-09-14 09:14:40'),(18,'Refresh','<ul><li>2 oz Coconut vodka</li><li>4 oz coconut water</li><li>Squeeze of lime</li></ul><p><br></p><p>Pour over ice</p>','2019-09-14 09:15:39','2019-09-14 09:15:39'),(19,'Mango Relaxer','<ul><li>2 oz Coconut vodka</li><li>4 oz mango nectar</li></ul><p><br></p><p>pour over ice</p>','2019-09-14 09:15:59','2019-09-14 09:15:59'),(20,'Hawaii Five-O','<ul><li>1 1/2 oz Coconut vodka</li><li>1/2 oz triple sec</li><li>4 oz pineapple juice</li><li>Squeeze of lime</li></ul><p><br></p><ol><li>Shake with ice</li><li>Pour into glass</li></ol>','2019-09-14 09:17:12','2019-09-14 09:17:12'),(21,'Westin Mystery Drink','<ul><li>1 pt rum</li><li>1 pt coconut rum</li><li>1 pt Passionfruit - Orange - Guava</li><li>Juice from 1/2 lime</li><li>1 pt Mai Tai Mix</li><li>Little Sprite or Sierra Mist</li></ul>','2019-09-14 09:21:02','2019-09-14 09:21:02'),(22,'Birdie','<ul><li>1.5 oz Vodka</li><li>.75 oz fresh lemon juice</li><li>.75 oz simple syrup</li><li>.5 oz pineapple juice</li><li>.5 oz Tempus Fugit Liqueur de Violettes</li></ul><p><br></p><p>Add all ingredients to a shaker. Shake, and then strain into a chilled coupe glass.  Garnish with dried flowers.</p>','2020-01-17 10:35:38','2020-01-17 10:35:38'),(23,'Butter Finger','<ul><li>1/4 oz Baily\'s Irish Cream</li><li>1/4 oz Butterscotch Schnapps</li><li>1/4 oz Kahlua</li><li>1/4 oz Vodka</li></ul>','2020-04-30 06:33:05','2020-04-30 06:33:05'),(24,'The Orchard','<p>1/3 whisky</p><p>1/3 pear and apple juice</p><p>1/3 Appletiser (a sparkling Apple juice)</p><p>Lots of ice</p>','2020-09-19 21:27:48','2020-09-19 21:27:48'),(25,'Beachside (Rocky Top)','<ul><li>Coconut Rum</li><li>Peach Schnapps</li><li>Orange Juice</li><li>Pineapple Juice</li><li>Lemon Wedge</li></ul>','2020-09-25 00:06:07','2020-09-25 00:07:13'),(26,'Negroni','<h2>Ingredients</h2><ul><li>1 ounce gin</li><li>1 ounce Campari</li><li>1 ounce sweet vermouth</li><li>Garnish: orange peel</li></ul><h2>Steps</h2><ol><li>Add all the ingredients into a mixing glass with ice, and stir until well-chilled.</li><li>Strain into a rocks glass filled with large ice cubes.</li><li>Garnish with an orange peel.</li></ol><p><br></p>','2020-10-20 05:47:15','2020-10-20 05:47:15'),(27,'Alaska Cocktail','<p>- 2.25 oz. Gin0</p><p>- .75 oz. Yellow Chartreuse1</p><p>- dash orange bitters</p><p><em>Stir on ice for 20 to 30 seconds. Strain off ice into chilled coupe glass, and garnish with a lemon peel.</em></p>','2020-10-25 20:59:15','2020-11-08 15:40:18'),(28,'Tipsy Grinch Punch','<ul><li>3 oz Peach Schnapps</li><li>3 oz Bicardi 151 Rum</li><li>12 oz Orange Juice</li><li>4 oz Sprite</li><li>3 oz Blue Curacao</li></ul><p><br></p><p>Mix in PC\'s quick stir pitcher and enjoy</p>','2020-10-28 23:59:36','2020-10-28 23:59:36'),(29,'Jack Frost','<ul><li>2 Tablespoons Sugar</li><li>1/2 Cup Cream of Coconut</li><li>1 Cup Pineapple Juice</li><li>3 Cups of Ice Cubes</li><li>1/2 Cup Curacao, Blue</li><li>1/2 Cup Vodka or Light Rum</li><li>1 Tablespoon Water</li><li>Rim with Coconut</li></ul>','2020-10-29 00:03:02','2020-10-29 00:03:02'),(30,'Pink Squirrel','<p>blend two scoops of vanilla ice cream with one ounce of white crème de cacao and one ounce of crème de noyaux (an almond-flavored liqueur that gives the drink its pretty color). Pour into a glass (a hurricane glass would be nice, or maybe a champagne coupe) and garnish with whipped cream and a cherry — and perhaps a little pink paper parasol.</p>','2020-11-24 10:19:28','2020-11-24 10:19:28'),(31,'Brandy Alexander','<p>mix an ounce and a half of cognac, an ounce of crème de cacao (either dark or white will do since the brandy already lends the drink a brown hue), and an ounce of cream. Shake over ice, strain, and garnish with a sprinkle of grated nutmeg.</p>','2020-11-24 10:20:56','2020-11-24 10:20:56'),(32,'Gin Rickey','<p>mix two ounces of gin with ¾ ounce of lime juice and then topping up your glass with soda water. The article also says it\'s somewhat similar to a gin and tonic, only without the tonic water</p>','2020-11-24 10:22:15','2020-11-24 10:22:15'),(33,'Sidecar','<p>Harry\'s original version called for equal parts of the drink\'s three ingredients, those being cognac, the orange liqueur Cointreau, and fresh lemon juice. The Tasting Room says that version is now known as \"French school,\" but there\'s also now an \"English school\" calling for two parts of cognac to one part of each of the remaining ingredients.</p>','2020-11-24 10:24:00','2020-11-24 10:24:00'),(34,'French 75','<p>Yes, champagne is one of the drink\'s main ingredients, as is gin, sugar, and lemon juice. A recipe published in the 1930 Savoy Cocktail Book calls for two parts of gin to one of lemon juice, a spoonful of powdered sugar, and champagne to fill a tall glass. Arnaud\'s French 75 Bar in New Orleans, however, makes the drink from which they took their name with cognac rather than gin. A fitting choice, since cognac is more of a French thing than the Brits\' favorite tipple, gin. Their recipe calls for 1 ¼ ounces of cognac, ¼ ounce simple syrup, and ¼ ounce fresh lemon juice, shaken over ice and strained into a champagne flute. Top the glass off with champagne, garnish with a twist of lemon peel, and oh là là! Vive le verre!</p>','2020-11-24 10:26:01','2020-11-24 10:26:01'),(35,'Delite Mandarin Margarita','<ul><li>1 oz Reposado Tequila</li><li>1/2 oz Mezcal</li><li>2 oz Delite Mandarin Juice</li><li>1/2 oz Agave Syrup (optional)</li><li>Sugar/Salt for rimming glass</li></ul>','2021-01-29 00:12:14','2021-01-29 00:12:14'),(36,'The Vasectomy','<p>https://www.youtube.com/watch?v=AwulM1sTrxc&t=105s</p><p><br></p><ul><li>Fill tall glass with ice</li><li>1 oz cranberry juice</li><li>3 oz tonic</li><li>Dash of lemon juice</li><li>1.5 oz Aviation American Gin</li></ul><p><br></p><p>Thanks Ryan Reynolds!</p>','2021-06-10 19:45:26','2021-06-10 19:46:32'),(37,'Mistery Drink','<ul><li>Hendricks Gin</li><li>St. Germain</li><li>Pineapple Juice</li><li>Grapefruit Juice</li></ul>','2021-06-22 22:25:36','2021-06-22 22:25:36'),(38,'Mistery Drink #2','<ul><li>Vanilla Vodka</li><li>Triple Sec</li><li>Cranberry Juice</li><li>Orange Juice</li><li>Lime</li></ul>','2021-06-22 22:30:20','2021-06-22 22:30:20'),(39,'The Earthquake Cocktail','<p><strong>Ingredients:</strong></p><ul><li>2 ounces cognac</li><li>1 ounce absinthe</li><li>lemon twist, for garnish</li></ul><p><br></p><p><strong>Method:</strong></p><ol><li>In an ice-filled mixing glass, combine the cognac and absinthe.</li><li>Stir until well-chilled.</li><li>Strain into a cocktail glass.</li><li>Garnish with the lemon twist.</li></ol><p><br></p>','2021-07-13 10:12:52','2021-07-13 10:12:52'),(40,'Whiskarita','<p>1 1/2 ounces 291 Fresh Colorado Whiskey</p><p>3/4 ounce triple sec</p><p>1 1/4 ounces lime juice</p><p>3/4 ounce simple syrup</p><p><br></p><p><em>Shake ingredients in a tin with ice. Strain over ice into Collins glass. Garnish with fresh lime wedge.</em></p>','2021-07-22 03:00:57','2021-07-22 03:00:57'),(41,'The Painkillee','<ul><li>2 oz. Pusser’s Rum</li><li>4 oz. pineapple juice</li><li>1 oz. orange juice</li><li>1 oz. coconut cream</li></ul><p><em>Shake on crushed or cracked ice for 4 to 6 seconds and dump contents into a tall glass or tiki mug. Top with more crushed ice. Garnish with a grind of nutmeg if you have it, or a slice or orange, or pineapple leaves, or all three.</em></p>','2021-07-31 04:37:36','2021-07-31 04:37:36'),(42,'Hurricane','<ul><li>8 oz rum</li><li>8 oz passion fruit jc</li><li>4 oz OJ</li><li>4 oz sweetened lime juice</li><li>2 oz simple syrup</li><li>2 oz grenedine</li></ul>','2021-09-06 01:16:32','2021-09-06 01:16:32'),(43,'Cucumber Fire','<ul><li>Effen Cucumber Vodka</li><li>Fresh Lemon Juice</li><li>Simple Syrup</li><li>Cucumber</li><li>Jalapeño</li></ul>','2021-09-11 00:59:40','2021-09-11 00:59:40'),(44,'Cranberry Collins','<h2>Ingredients</h2><ul><li>2 Cups (500 mL) sugar</li><li>12 - 13 sprigs rosemary, divided</li><li>2/3 cup (150 mL) fresh cranberries</li><li>1 cup (250 mL) lemon juice</li><li>2 cups (500 mL) gin</li><li>16 cups (4 L) ice, divided</li><li>4 cups (1 L) sparkling water</li></ul><p><br></p><h2>Directions</h2><ol><li>For the rosemary simple syrup, combine the sugar with 2 cups (500 mL) of water in a small saucepan; bring to a simmer over medium heat</li><li>When the sugar dissolves, remove the pan from the heat, add 4-5 sprigs of rosemary, and let them steep for 10 minutes.  Remove the rosemary after steeping.  Let the syrup cool completely before using.  Store, covered, in the refrigerator for up to 6 months.</li><li>Add the cranberries to a large pitcher and muddle them. -- Muddling helps release the flavors of the fresh ingredients, so they bind with the alcohol better</li><li>Add the lemon juice, gin, and 1 cup (250 mL) of the simple syrup to the pitcher.</li><li>When you\'re ready to serve, add up to 12 oz. (350 mL) of the mixture to a cocktail shaker.  Add 1 cup (250 mL) of ice to the shaker, seal, and shake vigorously</li><li>Strain the mixture into a chilled glass.  Top with sparkling water and garnish with a rosemary sprig.</li></ol>','2021-12-12 20:58:11','2021-12-12 20:58:11'),(45,'Whiskey Sour','<ul><li>2 oz. bourbon</li><li>0.75 oz. fresh lemon juice</li><li>0.75 oz. simple syrup</li><li>1 egg white</li></ul><p><em>Add all ingredients to a shaker tin. “Dry” shake ingredients without ice for five seconds to whip the egg. Add ice, seal tins and shake hard for 10 to 12 seconds. Strain into coupe or martini glass—it’ll come out white at first, and the color will emerge over the course of a minute under a paper-smooth head of foam. Express a lemon peel over the top of the foam for aroma and discard and decorate the foam with a few drops or dashes of Angostura Bitters.</em></p>','2022-06-29 23:06:50','2022-06-29 23:06:50'),(46,'Mint Julep','<ul><li>2.5 oz. bourbon</li><li>0.5 oz.-0.75 oz simple syrup (to taste)</li><li>10-12 mint leaves</li></ul><p><em>In a metal cup, gently muddle the mint into the simple syrup. Add bourbon, and fill 2/3 with crushed ice. Stir to chill, until a frost forms on the outside. Then pack the rest of the cup with ice. Take two mint crowns, lightly bruise them with your fingers, and stick them against the inside close to the straw. Enjoy.</em></p><p><br></p><p><br></p>','2022-06-29 23:07:20','2022-06-29 23:07:20'),(47,'New York Sour','<ul><li>2 oz. rye whiskey</li><li>0.75 oz. lemon juice</li><li>0.75 oz. simple syrup (1:1 sugar to water)</li><li>0.5 to 1 oz. light red wine</li></ul><p><em>Add rye, lemon juice and simple syrup to the shaker tin with ice and shake hard for 10 to 12 seconds. Strain over fresh ice in a rocks glass, leaving 0.5-inch clearance on the top of the glass. Top with between 0.5 oz. and 1 oz. of light red wine.</em></p>','2022-06-29 23:07:48','2022-06-29 23:07:48'),(48,'Gold Rush','<ul><li>2 oz. bourbon</li><li>0.75 oz. lemon juice</li><li>0.75 oz. honey syrup</li><li><em>1 grapefruit peel, maybe 1” x 2”, taking care to get as little of the white pith as possible</em></li></ul><p><em> Add all ingredients, including grapefruit peel, to a cocktail shaker with ice. Shake hard over ice for 8 to 10 seconds, and strain into rocks glass over fresh ice. Garnish with a lemon wheel or peel. </em></p><p><br></p><p><br></p>','2022-06-29 23:08:13','2022-06-29 23:08:13'),(49,'Amaretto Sour','<ul><li>1.5 oz. amaretto</li><li>0.75 oz. cask-strength bourbon</li><li>1 oz. lemon juice</li><li>0.25 oz. simple syrup (to taste)</li><li>1 egg white</li></ul><p><em>Add all ingredients to a cocktail shaker and shake without ice for five to seven seconds to whip the egg white. Add ice and shake hard for eight to 10 seconds. Strain either over fresh ice in a large rocks glass or up in a coupe. Garnish with a lemon peel and, if you like, a cherry.</em></p>','2022-06-29 23:08:51','2022-06-29 23:08:51'),(50,'Japanese Whisky Highball','<ul><li>1.5 oz. Japanese whisky</li><li>4.5 oz. chilled soda or seltzer water</li></ul><p><em>Make sure all ingredients and tools are as cold as possible. Add ice to a tall narrow glass pulled from the freezer and add chilled whisky. Gently pour soda water down the side of the glass. Stir minimally, to combine ingredients but to agitate the bubbles as little as possible. Express a lemon peel over the top and discard. </em></p>','2022-06-29 23:09:12','2022-06-29 23:09:12'),(51,'Paper Plane','<ul><li>0.75 oz. bourbon</li><li>0.75 oz. lemon juice</li><li>0.75 oz. Amaro Nonino</li><li>0.75 oz. Aperol</li></ul><p><em>Add all ingredients to a cocktail shaker with ice and shake for six to 10 seconds. Strain up into a coupe or cocktail glass. Garnish by hitting play on M.I.A.’s 2008 banger “Paper Planes.”</em></p><p><br></p>','2022-06-29 23:09:35','2022-06-29 23:09:35'),(52,'Butterbeer (Non Alcoholic)','<p><em>Yield 4 glasses</em></p><p><em>Cook time 25 minutes</em></p><h2>Ingredients:</h2><ul><li>½ cup (1 stick) butter</li><li>1 cup brown sugar</li><li>1 teaspoon kosher salt</li><li>2 teaspoons vanilla extract</li><li>1 cup heavy whipping cream</li><li>20 ounces lemon-lime soda</li><li>ice</li></ul><h2>Instructions:</h2><p>1. In a medium saucepan over medium-low heat, melt the butter.</p><p>2. When the butter is melted, add the brown sugar, salt and vanilla extract. Whisk to combine.</p><p>3. Cook the mixture for 5 minutes, until the brown sugar is completely dissolved.</p><p>4. Whisk in the heavy whipping cream and continue to cook for 1 minute.</p><p>5. Allow this mixture to cool to room temperature, 15 minutes.</p><p>6. When cool, divide between 4 large glasses filled halfway up with ice.</p><p>7. Slowly top with soda, but be careful not to overfill, as the mixture will bubble and foam. Stir to blend and enjoy.</p>','2022-09-21 21:40:58','2022-09-21 21:40:58'),(53,'Jack Skellington’s Haunted White Russian','<ul><li>Homemade spiced brown sugar simple syrup</li><li>vodka</li><li>Kahlúa</li><li>shot of espresso for an extra frightful kick</li><li>Splash of cream</li></ul><p><br></p><p>Notes:</p><p><br></p><p>To make the sweet brown sugar and vanilla spice syrup, mix brown sugar with pumpkin butter, pumpkin spice, vanilla, and water. Simmer until the sugar dissolves.</p><p><br></p><p>If you’re not a fan of pumpkin or simply do not have any pumpkin butter, you can omit both the pumpkin butter and pumpkin spice</p><p><br></p><p>When the syrup is cool, mix together your classic White Russian ingredients, vodka and Kahlua. Then add an extra shot of espresso and cream.</p>','2022-10-14 03:41:45','2022-10-14 03:41:45'),(54,'Candy Corn Jello Shots','<h4><strong>Yellow Layer</strong></h4><ul><li>1.5 ounces lemon jello mix</li><li>1/2 cup hot water</li><li>1/2 cup cake vodka 4 ounces</li></ul><h4><strong>Orange Layer</strong></h4><ul><li>1.5 ounces orange jello mix</li><li>1/2 cup hot water</li><li>1/2 cup cake vodka 4 ounces</li></ul><h4><strong>White Layer</strong></h4><ul><li>.25 ounce unflavored gelatin</li><li>1/2 cup hot water</li><li>1/2 cup cake vodka 4 ounces</li><li>14 ounces sweetened condensed milk 1 can</li></ul><h4><strong>Garnish</strong></h4><ul><li>whipped cream</li><li>candy corns</li></ul><p><br></p><p><br></p><h3><strong>Things You’ll Need</strong></h3><ul><li>16 2.5 ounce shot glasses</li></ul><h3><strong>Instructions</strong></h3><ul><li>For the first layer, in a small, spouted mixing bowl or measuring cup (2 cups in size) whisk Lemon Jell-O and hot water until dissolved. Mix in Cake vodka and pour evenly into 16 2.5-ounce shot glasses (about .8-ounce). Set in the fridge for at least 60 minutes to set before starting the orange layer.</li><li>For the second layer, follow the same directions as you did with the first layer. In a small, spouted mixing bowl or measuring cup (2 cups in size) whisk Orange Jell-O and hot water until dissolved. Mix in Cake vodka and pour evenly into the shot glasses. Set in the fridge for at least 60 minutes to set before starting the white layer.</li><li>In a small, spouted mixing bowl or measuring cup whisk the package of unflavored gelatin and hot water until dissolved. Mix in Cake vodka, then 1 can of sweetened condensed milk, and pour evenly into the shot glasses. Set in the fridge for at least 60 minutes to set before serving.</li><li>Top with whipped cream and candy corn just before serving.</li></ul>','2022-11-11 02:27:16','2022-11-11 02:27:16'),(55,'Cloudy Night','<p>This cocktail is perfect as an aperitif to warm you up on those chilly evenings.</p><p><br></p><p>2 oz Cointreau Noir</p><p>4 oz cloudy apple juice</p><p>2 dashes of aromatic bitters</p><p>2-3 apple slices</p><p><br></p><p>Stir over ice and garnish with slices of apple</p>','2023-06-11 19:07:17','2023-06-11 19:07:17'),(56,'Bee\'s Knees','<p>This classic prohibition cocktail made with The Botanist Gin, is the perfect holiday brunch cocktail.</p><p><br></p><p>2 oz The Botanist Gin</p><p>.75 oz fresh lemon juice</p><p>.75 oz honey simple syrup 1:1</p><p><br></p><p>Shake over ice then strain into a chilled cocktail glass. Garnish with a lemon twist.</p>','2023-06-11 19:09:11','2023-06-11 19:09:11'),(57,'Original Old Fashion','<p>Try this revival of the original cocktail to elevate your holiday drinks.</p><p><br></p><p>1.5 oz Mount Gay Extra Old</p><p>2 dashes of angostura bitters</p><p>1 teaspoon of sugar</p><p>1 orange peel + 1 orange slice</p><p>1 maraschino cherry</p><p><br></p><p>Muddle orange peel with rum and sugar. Remove peel, add bitters, then pour over ice and add garnish.</p>','2023-06-11 19:11:09','2023-06-11 19:11:09'),(58,'Rumhattan','<p>Try a fun twist on this classic cocktail by using Mount Gay Black Barrel Rum</p><p><br></p><p>2 oz Mount Gay Black Barrel Rum</p><p>.5 oz Sweet Vermouth</p><p>2-3 dashes of angostura bitters</p><p>1 maraschino cherry</p><p><br></p><p>Mix ingredients over ice, stir well, and strain into a chilled cocktail glass. Garnish with cherry.</p>','2023-06-11 19:12:46','2023-06-11 19:12:46'),(59,'Apple Rickey','<p>Fresh rosemary evokes a sense that the holiday season is near.</p><p><br></p><p>2 oz Cointreau</p><p>1 oz fresh lime juice</p><p>3 slices tart apple</p><p>7 leaves fresh rosemary</p><p>3-4 oz club soda</p><p><br></p><p>Muddle the apple and rosemary, then add Cointreau and lime juice with ice, and top with club soda.</p>','2023-06-11 19:14:21','2023-06-11 19:14:21'),(60,'Royal Side Car','<p>The first iconic Cointreau cocktail, the Sidecar, traces its heritage back to 1920s London. A beautiful warm up for any holiday cocktail party!</p><p><br></p><p>1 oz Remy Martin 1738 Accord Royal</p><p>1 oz Cointreau</p><p>.5 oz lemon</p><p><br></p><p>Shake with ice and then strain into your best coupe glass</p>','2023-06-11 19:16:10','2023-06-11 19:16:10'),(61,'Sazerac','<section class=\"comp section--ingredients section\"><header class=\"section__header \"><h2 class=\"section__title section__title--bold-underline\">Ingredients</h2></header><div class=\"loc section-content section__content \"><div class=\"comp structured-ingredients\"><ul class=\"structured-ingredients__list text-passage\"><li class=\"structured-ingredients__list-item\"><p><span>Absinthe</span><span>, to rinse</span></p></li><li class=\"structured-ingredients__list-item\"><p><span>1</span>&#160;<span>sugar cube</span></p></li><li class=\"structured-ingredients__list-item\"><p><span>1/2</span>&#160;<span>teaspoon</span>&#160;<span>cold water</span></p></li><li class=\"structured-ingredients__list-item\"><p><span>4</span>&#160;<span>dashes</span>&#160;<span>Peychaud&#8217;s bitters</span></p></li><li class=\"structured-ingredients__list-item\"><p><span>2 1/2</span>&#160;<span>ounces</span>&#160;<span>rye whiskey</span></p></li><li class=\"structured-ingredients__list-item\"><p>Garnish:&#160;<span>lemon peel</span></p></li></ul></div></div></section><div class=\"comp mntl-native mntl-native--labeled\"><div class=\"comp mntl-native__adunit mntl-gpt-dynamic-adunit mntl-gpt-adunit gpt native dynamic is-requested\"></div></div><section class=\"comp section--instructions section\"><header class=\"section__header \"><h2 class=\"section__title section__title--bold-underline\">Steps</h2></header><div class=\"loc section-content section__content \"><div class=\"comp text-passage structured-content structured-project__steps mntl-sc-page mntl-block\"><ol class=\"comp mntl-sc-block-group--OL mntl-sc-block mntl-sc-block-startgroup\"><li class=\"comp mntl-sc-block-group--LI mntl-sc-block mntl-sc-block-startgroup\"><p class=\"comp mntl-sc-block mntl-sc-block-html\">Rinse a chilled rocks glass with absinthe, discarding any excess, and set aside.</p><div class=\"comp mntl-sc-block mntl-sc-block-adslot mntl-block\"></div></li><li class=\"comp mntl-sc-block-group--LI mntl-sc-block mntl-sc-block-startgroup\"><p class=\"comp mntl-sc-block mntl-sc-block-html\">In a mixing glass, muddle the sugar cube, water and the Peychaud&#8217;s bitters.</p><div class=\"comp mntl-sc-block mntl-sc-block-adslot mntl-block\"></div></li><li class=\"comp mntl-sc-block-group--LI mntl-sc-block mntl-sc-block-startgroup\"><p class=\"comp mntl-sc-block mntl-sc-block-html\">Add the rye whiskey, fill the mixing glass with ice and stir 15&#173;&#8211;20 seconds, until well-chilled.</p><div class=\"comp mntl-sc-block mntl-sc-block-adslot mntl-block\"></div></li><li class=\"comp mntl-sc-block-group--LI mntl-sc-block mntl-sc-block-startgroup\"><p class=\"comp mntl-sc-block mntl-sc-block-html\">Strain into the prepared glass.</p><div class=\"comp mntl-sc-block mntl-sc-block-adslot mntl-block\"></div></li><li class=\"comp mntl-sc-block-group--LI mntl-sc-block mntl-sc-block-startgroup\"><p class=\"comp mntl-sc-block mntl-sc-block-html\">Twist the lemon peel over the drink&#8217;s surface to express the peel&#8217;s oils, then garnish with the peel.</p></li></ol></div></div></section>','2024-05-01 23:47:33','2024-05-06 18:56:29'),(62,'Butter Beer','2 oz Vanilla Vodka<div>2 oz Butterscotch Schnapps</div><div>2 oz cream soda</div><div>Whip cream</div><div>Carmel syrup</div>','2024-12-27 22:41:17','2024-12-27 22:41:17');
/*!40000 ALTER TABLE `drinks` ENABLE KEYS */;
