  `end_date` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bullets` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
