INSERT INTO `employment_records` VALUES (1,'Google','Data Center Technician','The Dalles, OR','Jun 2008','Mar 2009','<ul><li>Monitored, diagnosed, repaired, and upgraded over 16,000 servers’ hardware</li><li>Increased overall accuracy and productivity by instructing weekly Linux classes</li></ul>','2018-02-11 05:32:25','2019-08-31 01:03:11'),(3,'Zenuity','Web Developer','Scottsdale, AZ','Aug 2009','Mar 2011','<ul><li>Built and customized Drupal 6 websites for clients</li><li>Automated contract generation process shaving hours of tedious writing per month</li><li>Established best practices for developing client websites</li><li>Automated Drupal website deployment using sed, perl, php, and mysql</li></ul>','2018-02-11 05:34:51','2019-11-18 13:36:10'),(4,'Novus Biologicals','Drupal Developer','Littleton, CO','Apr 2011','Dec 2012','<ul><li>Maintained and developed modules for Drupal 6 web store running Ubercart</li><li>Streamlined website development by migrating to Acquia’s Drupal hosting service</li><li>Implemented necessary changes to make website PCI compliant</li><li>Tripled search speeds by integrating Solr search functionality</li><li>Decreased page load times over 3000% by adopting industry best practices</li><li>Automated data synchronization process from Microsoft to LAMP stack using Samba and rsync</li><li>Maintained database holding availability and pricing for over 250,000 products</li></ul>','2018-02-11 05:35:43','2019-11-18 13:42:36'),(5,'ProKarma','Web Developer','Greenwood Village, CO','Dec 2012','Dec 2013','<ul><li>Guided company to adopt traditional software development life-cycle best practices and tools</li><li>Developed customized, JavaScript-driven applications for managing stock in warehouses</li><li>Wrapped client\'s antiquated, proprietary software with more robust, updated PHP tool set</li></ul>','2018-02-11 05:36:44','2019-11-18 13:50:03'),(6,'Return Path','Software Engineer','Broomfield, CO','Aug 2013','May 2014','<ul><li>Added features to improve user experience in feedback loop and global trap exchange tool suite</li><li>Implemented Angular widgets throughout our product suites as part of a company-wide standardization</li><li>Wrote a Git extension in Go for Gerrit interactions to bring web interactions to the command line</li><li>Created a mock data feed for testing our Outbound Abuse Manager product</li><li>Modified our Kafka consumer to deliver a wider set of trap data to subscribing customers</li></ul>','2018-02-11 05:41:11','2019-11-18 14:15:42'),(7,'PVBid','Lead Developer and Co-Founder','Denver, CO','Dec 2013','May 2016','<ul><li>Created a bidding system to improve the efficiency and accuracy of PV system installation costs</li><li>Designed and deployed a REST/SOAP API backed by PHP and MySQL</li><li>Built proof-of-concept used for fund-raising and investor pitches</li><li>Worked with customers to set priorities, expectations, and deadlines</li><li>Managed a team of consultants to meet customer expectations and deadlines</li><li>Partitioned workload to hand off to contractors and tracked project development status</li><li>Reported application development status to CEO</li><li>Leveraged AWS infrastructure to deploy multiple environments using EC2 and Route 53</li><li>Wrote requirements document for Sunshot incubator development</li><li>Created Jenkins build job to facilitate graceful product deployment</li><li>Maintained CentOS system backups and security updates</li></ul>','2018-02-11 05:42:12','2019-11-18 14:22:10'),(8,'By the Pixel','Software Engineer','Denver, CO','May 2016','Dec 2017','<ul><li>Built a price estimation application on Angular2 backed by a Laravel API for DenverDovetail.com</li><li>Maintained, developed features, and wrote tests for IDEXX\'s Petly Plans application</li><li>Contributed to Ruby on Rails apps such as UrgentCareLocations.com and DomesticShelters.org</li><li>Standardized deploy process across all applications</li></ul>','2018-02-11 05:43:20','2019-08-31 01:02:13'),(10,'Colorado Department of Education','Web Developer','Denver, CO','Mar 2018','Feb 2020','<ul><li>Collaborated on “Consolidated Application” used to manage Colorado school district funding</li><li>Created a micro framework I named “Antiquated PHP Framework (APF) patterned after Laravel to standardize and add efficiency to the office’s web development process</li><li>Leveraged APF to build a web tool districts could use to apply for construction grants</li><li>Utilized Docker to provision suitable development environment for all developers in the office</li></ul>','2018-04-16 13:52:02','2021-01-28 16:59:22'),(11,'SpotX / Magnite','Software Engineer','Broomfield, CO','Feb 2020',NULL,'<ul><li>Drove the development of features to enhance campaigns’ targeting rules for our customers</li><li>Ensured continued progress on features during company reorganization and acquisition</li><li>Tackled high priority issues, triaging to appropriate teams where necessary</li><li>Participated in design and infrastructure planning meetings, lending advice where appropriate</li><li>Troubleshot release-process issues in Jenkins and Openshift</li><li>Answered questions posed by other teams regarding UI and API tools</li><li>Conducted code reviews to ensure conformity to SOLID principles and sound design decisions</li></ul>','2021-01-28 16:58:27','2021-11-09 17:55:11');
