INSERT INTO `orders` VALUES (1,1,'Spicy Chicken Sandwich','<ul><li>No MAYO</li><li>No Lettuce</li><li>No tomatoes</li><li>Add cheese (American is OK at Wendy\'s)</li></ul>','2018-01-22 04:06:24','2020-01-08 08:04:22'),(2,1,'Asiago Ranch Sandwich','<p>Spicy chicken filet</p><p>No BACON</p><p>No lettuce</p><p>Medium sized meal</p><p>Dr Pepper</p><p><br></p><p>Chicken nuggets and chocolate milk or juice</p>','2018-01-22 04:07:22','2020-11-20 19:09:28'),(3,2,'Primary','<ul><li>Nacho Supreme, no refried beans</li><li>2x Chalupa Supreme w/ ground beef, no lettuce</li><li>2x Cheesy Rollup</li></ul>','2018-08-23 00:38:24','2020-09-19 14:43:45'),(4,3,'Chicken Fingers','<ul><li>Frank\'s red hot and Ranch</li></ul>','2018-11-19 01:26:32','2019-10-14 22:40:02'),(5,4,'Buffalo Chicken Sandwich','<ul><li>No lettuce</li><li>Spoon bender (Oregon blackberry)</li><li>Wild Fries</li></ul><p><br></p><ul><li>Corn Dog</li></ul>','2019-02-16 07:41:35','2021-07-13 01:37:06'),(6,5,'Meal Deal','<ul><li>Cheese Slices</li><li>Ranch</li><li>Hot pepper flakes</li><li>Mr. Pibb</li><li>Garlic cheese knots</li></ul>','2019-04-25 21:34:39','2019-10-14 22:41:32'),(7,4,'Chicken Tenders','<ul><li>Chicken Tenders</li><li>1 x Buffalo Sauce</li><li>2 x Ranch</li><li>Wild fries</li><li>Doctor Pepper</li></ul><p><br></p><ul><li>Jasper: Smallest Chx Tender Count</li></ul>','2019-07-15 06:05:14','2019-11-11 02:28:42'),(8,6,'Spicy Deluxe','<ul><li>No lettuce</li><li>Dr. Pepper</li><li>1 Polynesian</li><li>1 Ketchup</li><li>Chicken/Fries</li></ul>','2019-08-08 06:08:26','2019-10-14 22:41:57'),(9,7,'Buzz Clux and Fries','<ul><li>Extra Fries</li><li>Ranch and Blue Cheese</li></ul>','2019-11-02 06:03:37','2019-11-02 06:04:50'),(10,8,'Double (Used to be \"Middy\")','<ul><li>No sauce</li><li>Swiss cheese</li></ul>','2020-01-23 08:12:05','2020-01-23 08:12:05'),(11,4,'Number 3','<p>3 corn dogs</p><p>Kid Mac n cheese</p><p>Beer battered onion rings</p><p><br></p>','2020-05-02 06:47:48','2020-05-02 06:47:48'),(12,9,'Primary','<p>Bibb lettuce salad, no pachetta, add grilled chicken</p><p><br></p><p>Mini calzone with pepperoni</p><p><br></p><p>Margarita Pizza (sm)</p><p><br></p><p>Chicken Parm</p>','2020-05-03 07:29:50','2020-05-03 07:29:50'),(13,10,'Go To Order','<p>Javalina - Spicy level half and half.</p><p>Classic, no meat or green chilis for Jasper</p>','2020-05-09 23:06:41','2020-06-14 14:24:03'),(14,11,'Main','<ul><li>2 orders pork egg roles</li><li>2 Pad Thai, mild +</li><li>Chicken Satay</li></ul><p><br></p>','2020-05-11 06:20:57','2020-05-11 06:20:57'),(15,8,'Family Order','<ul><li>Pizza slider w/ apple sauce and choc. milk</li><li>Spicy Greek Gyro</li><li>2 French Dips</li></ul>','2020-05-13 23:58:13','2020-05-13 23:58:13'),(16,12,'Jessica\'s','<ul><li>Quarter pounder meal, extra mustard and onions</li><li>Coke</li><li>Medium</li></ul>','2020-05-14 23:37:53','2020-05-14 23:37:53'),(17,13,'Family','<p>Butterfinger blizzard</p><p>Chicken strip meal</p><p>Ranch ketchup</p>','2020-05-18 00:57:58','2020-05-18 00:57:58'),(18,14,'Family Meal','<p>15 pieces chicken family Meal</p><p>Honey Butter Buscuits</p><p>Mashed potatoes</p><p><br></p>','2020-08-17 02:30:49','2020-08-17 02:31:35'),(19,15,'Main order','<ul><li>Five cheese or green chili cheese bagel with salsa schmeer, smaller pron of turkey</li><li>French Toast bagel toasted with butter</li></ul>','2020-09-26 16:06:14','2020-09-26 16:06:14'),(20,16,'Shake Shack Stacker','<p>This is the burger with the mushroom</p>','2020-10-23 23:36:09','2020-10-23 23:37:07'),(21,16,'Green Chili something','<p>Yep</p>','2020-10-23 23:36:46','2020-10-23 23:36:46'),(22,11,'Drunken Noodles','<ul><li>Chicken drunken noodles</li><li>No snap peas</li><li>No bean sprouts</li><li>Pork egg rolls</li><li><br></li></ul>','2020-11-19 23:28:12','2020-11-19 23:28:12'),(23,17,'Food','<p>Cheese casadilla</p><p>Pico de gallo</p><p>White rice</p><p><br></p><p>Guac and chips</p><p>Cheese casadilla</p><p><br></p><p>Coke</p>','2020-11-21 21:18:47','2020-11-21 21:19:19'),(24,18,'Regular','<ul><li>Taco</li><li>No homine</li><li>No beans</li></ul><p><br></p><ul><li>Kids order</li></ul><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p>','2020-12-07 23:41:50','2020-12-07 23:41:50'),(26,19,'Jessica','<p>Buffalo Wrap with tots</p>','2021-01-20 01:18:06','2021-01-20 01:18:06'),(27,19,'Jasper','<p>Cheeseburger with just ketchup</p>','2021-01-20 01:18:54','2021-01-20 01:18:54'),(28,20,'Jessica','<p>Joey</p><p><br></p>','2021-01-31 19:38:31','2021-01-31 19:38:31');
